})

-- Dialogs and progress windows float instead of taking half the screen
hl.window_rule({
    name   = "modal-dialogs",
    match  = { modal = true },
    float  = true,
    center = true,
})

hl.window_rule({
    name   = "progress-dialogs",
    match  = { initial_title = "^(Downloading|Installing|Updating|Extracting|Copying|Moving|Deleting|Progress).*" },
    float  = true,
    center = true,    size   = "600 200",
})

hl.window_rule({
